  str_n29_1_name_desc = "—",
  str_n29_2_name_desc = "Kebakaran terjadi pada upacara peresmian. Anda bergegas ke dalam api untuk menyelamatkan seorang gadis kecil yang terjebak. Saat ini, Dark Slayer muncul di hadapanmu...",
  str_n29_3_name_desc = "—",
  str_n29_4_name_desc = "Kristen mulai menyelidiki lokasi kebakaran di gudang panti asuhan.",
  str_n29_5_name_desc = "Sebelum waktu yang disepakati untuk menukar liontin, Hati memiliki percakapan yang mendalam dengan Anda di hutan.",
  str_n29_6_name_desc = "Ini adalah hutan dekat Umbraton, tempat tinggal Eclipsites.",
  str_n29_7_name_desc = "—",
  str_n29_8_name_desc = "Hati sangat gelisah. Kenangan masa kecilnya dan ibunya melintas di benaknya seperti lentera yang berputar.",
  str_n29_9_name_desc = "Kristen mulai menyelidiki panti asuhan tua dan bertemu Grimme, yang diserang oleh Eclipsites.",
  str_n29_10_name_desc = "—",
  str_n29_11_name_desc = "Anda berhasil membujuk Kristen untuk mempertimbangkan kembali apakah Hati benar-benar pembakar.",
  str_n29_12_name_desc = "Itu tidak akan mudah untuk Hati, yang diinginkan oleh seluruh kota, untuk masuk ke dalam Umbraton.",
  str_n29_13_name_desc = "Kristen, Hati, dan Zenas berkumpul di panti asuhan. Dendam, baik lama maupun baru, akan diselesaikan di sini.",
  str_n29_14_name_desc = "Hati mengambil kembali liontin milik ibunya. Dia harus menghadapi iblis batinnya dengan berani sebelum mengungkapkan rahasia liontin itu.",
  str_n29_1_name_desc_long = "Atas undangan Bethel, Anda datang ke Umbraton untuk menghadiri upacara peresmian Panti Asuhan Umbraton. Kristen dan Zenas dari Lumo Hall of Justice bertanggung jawab atas keamanan acara. Mereka memberi tahu Anda bahwa keadaan tidak damai di Umbraton baru-baru ini dan bahwa seorang pembakar berantai bernama Dark Slayer telah berkeliaran di mana-mana di Umbraton.",
  str_n29_2_name_desc_long = "Gudang panti asuhan terbakar. Anda merasakan bahwa seorang gadis kecil terjebak di gudang, jadi Anda bergegas masuk ke dalam api untuk menyelamatkannya terlepas dari konsekuensinya. Seseorang menyelamatkan Anda saat balok bangunan akan runtuh setelah terbakar. Anda mengenali bahwa orang ini adalah Pembunuh Kegelapan di poster buronan.",
  str_n29_3_name_desc_long = "Anda bangun di Firefly Bar. Pemiliknya, Grimme, memberi tahu Anda nama asli Dark Slayer Hati dan bahwa dia bukan pembakar serial. Setelah mendengar keseluruhan cerita, Anda memutuskan untuk membantu Hati mengembalikan ingatannya yang hilang...",
  str_n29_4_name_desc_long = "Setelah menyelidiki kebakaran dalam dua bulan terakhir, Kristen menemukan bahwa korban kebakaran semuanya terkait dengan panti asuhan tua. Pada saat yang sama, Hati memutuskan untuk menukar Anda dengan liontin yang dibawa Zenas.",
  str_n29_5_name_desc_long = "Tuan Hamell menolak untuk bekerja sama dengan penyelidikan Kristen, dan Zenas menghibur mereka yang frustrasi Kristen. Di sisi lain, Anda dan Hati diserang oleh sejumlah besar Eclipsites di hutan dekat Umbraton. Dalam situasi kritis, Hati menggunakan kekuatannya, yang selalu dilarang.",
  str_n29_6_name_desc_long = "—",
  str_n29_7_name_desc_long = "Ini adalah waktu yang disepakati, dan orang yang datang adalah Tuan Hamell?! Tuan Hamell dibunuh di tengah percakapan, dan Kristen dan Zenas muncul untuk menangkap Hati. Topeng Zenas terlepas secara tidak sengaja, memperlihatkan bekas luka yang mengejutkan di separuh wajahnya dalam bayang-bayang.",
  str_n29_8_name_desc_long = "Hati menjadi sangat gelisah saat Zenas menunjukkan wajahnya. Dia melarikan diri dari tempat kejadian dengan Anda, tetapi terjebak dalam kenangan masa kecilnya dengan ibunya dan tidak bisa mendapatkan kembali ketenangannya. Kapan Hati masih kecil, dia merasa seperti monster karena ibunya melarang dia keluar rumah dan menggunakan kekuatannya. Ibunya bahkan mendorongnya ke perapian.",
  str_n29_9_name_desc_long = "Kristen ingin tahu apa yang terjadi di panti asuhan tua, jadi dia mengunjungi dua anak yatim piatu yang pernah tinggal di sana dan sekarang tinggal di Lumopolis Bawah. Dalam perjalanan kembali ke Umbraton, Kristen menyelamatkan Grimme dari serangan Eclipsite. Grimme mengundang Kristen untuk minum di bar dan memberitahu Kristen cerita setengah kebenaran.",
  str_n29_10_name_desc_long = "Hati kembali ke tempat dia pernah tinggal bersama ibunya. Dia berdiri di perapian untuk mencoba mengingat apa yang terjadi saat itu. Gambar dari Kristen berlarian membangkitkan ingatan Hati. Pada hari ibu Hati mendorongnya ke perapian, seorang pria mendobrak masuk ke dalam rumah, membunuh ibunya secara brutal, dan mengambil liontin berharga itu.",
  str_n29_11_name_desc_long = "Setelah mendapatkan kembali ingatannya, Hati menuduh bahwa Zenas adalah pelaku sebenarnya yang masuk ke rumahnya, membunuh ibunya, dan mengambil liontin itu. Bekas luka di wajah Zenas adalah buktinya. Kristen tidak setuju, menunjukkan bahwa Zenas mendapatkan bekas luka itu untuk menyelamatkannya. Kedua belah pihak berdebat dengan panas, jadi Anda mengusulkan untuk menemukan bukti kritis, liontin itu.",
  str_n29_12_name_desc_long = "—",
  str_n29_13_name_desc_long = "Kristen menemukan Zenas di panti asuhan dan memohon Zenas untuk menyerahkan liontin itu untuk membuktikan bahwa dia tidak bersalah. Anda dan Hati muncul dan jelaskan alasanmu, tapi Zenas berpikir Kristen telah berkolusi denganmu selama ini. Dalam kemarahan yang memalukan, Zenas mengambilnya Kristen sandera dan ingin menyematkan semua kejahatan padamu.",
  str_n29_14_name_desc_long = "Dengan bantuan Anda, Hati mengatasi iblis batinnya dan menggabungkan liontin ibunya dengan miliknya. Foto keluarga Hati jatuh dari ruang tersembunyi di liontin, yang merupakan harta paling berharga dari ibu Hati. Dengan berkah matahari dan gadis kecil itu, Hati mengambil langkah pertamanya menuju masa depan yang baru.",
  str_n29_h1_name = "H1 - Pengepungan",
  str_n29_h2_name = "H2 - Ular Panjang",
  str_n29_h3_name = "H3 - Bentuk Rusak",
  str_n29_h4_name = "H4 - Isolasi",
  str_n29_h1_name_desc = "Rute kemajuan mereka sangat aneh. Bisakah seseorang mengarahkan mereka? Atau berlatih dengan taktik baru?",
  str_n29_h2_name_desc = "Mengapa musuh membentuk barisan panjang? Kita tidak bisa membiarkan jumlah mereka bertambah seperti ini... Apakah lebih baik menyerang titik tertentu untuk menembus garis?",
  str_n29_h3_name_desc = "Tanahnya retak di hutan belantara yang terjal dan rusak. Bagaimana Anda bisa mengalahkan musuh Anda dengan cepat jika Anda kesulitan mendekati mereka?",
  str_n29_h4_name_desc = "Medannya menyulitkan pihak kami untuk bergerak. Secara alami, musuh juga terpengaruh. Mungkin kita bisa memanfaatkan ini?",
